class Solution { fun maxBuilding(n:Int,restrictions:Array<IntArray>):Int{val limits=(restrictions.map{it.clone()}+listOf(intArrayOf(1,0),intArrayOf(n,n-1))).sortedBy{it[0]};for(i in 1 until limits.size)limits[i][1]=minOf(limits[i][1],limits[i-1][1]+limits[i][0]-limits[i-1][0]);for(i in limits.size-2 downTo 0)limits[i][1]=minOf(limits[i][1],limits[i+1][1]+limits[i+1][0]-limits[i][0]);var answer=0;for(i in 1 until limits.size)answer=maxOf(answer,(limits[i-1][1]+limits[i][1]+limits[i][0]-limits[i-1][0])/2);return answer} }
